import numpy as np

def r(x):
    return float(x) / 2.0

def R(y_orig, y_new):
    e0 = np.abs(float(y_orig) - 1.0)
    e1 = np.abs(float(y_new) - 1.0)
    if e0 < 1e-15:
        return bool(e1 < 1e-15)
    order = np.log(e1 / e0) / np.log(0.5)
    return bool(np.abs(order - 2.0) <= 0.2)
